/**
 * **GENERATED — do not edit.** The resolution-independent typing preamble, baked from the runtime's
 * built `.d.ts` by `scripts/gen-preamble.ts`. Regenerate after a runtime typed-surface change;
 * the `preamble-sync` test guards drift. See `./preamble-gen.ts`.
 */

/** The typing preamble prepended to every virtual `.tsx` (ambient runtime module + prelude globals). */
export const PREAMBLE = "/**\n * The **Nota-owned** per-tag HTML attribute map — the type surface `h(\"tag\", props, …)` checks\n * `props` against (the typed emit surface; design/decode.md §The typed surface).\n *\n * This is deliberately *not* React's `JSX.IntrinsicElements`: the reader lowers markup to `h(...)`\n * *calls*, not JSX, and emits framework-neutral HTML attribute names (`class`, not `className`;\n * `for`, not `htmlFor`) plus reader-synthesised host tags (`nota-ul-li`). We seed a representative\n * set of common elements with their distinctive attributes and let every other tag — custom\n * elements, the `nota-*` sentinels, anything — fall through the string index signature so it stays\n * legal (unknown tags never error — that is the \"never lie\" surface).\n *\n * Each element type intersects {@link NotaGlobalAttributes} (which carries a permissive\n * `[attr: string]: unknown` index) with its element-specific attributes, so:\n * - known attributes get **completion** and **value checking** (`h(\"a\", { href: 123 })` errors —\n *   `href` is `string`), while\n * - unknown attributes are **allowed** (`h(\"a\", { \"data-x\": 1, whatever: true })` is fine).\n */\n/**\n * Attributes valid on every host element: the HTML global attributes, the reader's `key` (a\n * reconciliation hint that rides through props), and a permissive index signature so an element\n * never rejects an attribute it does not explicitly list (custom `data-*`, framework props, ARIA).\n * Named members are checked against their declared types; everything else is `unknown`.\n */\ninterface NotaGlobalAttributes {\n    /** Element id. */\n    id?: string;\n    /** Space-separated class list (HTML `class`, not React's `className`). */\n    class?: string;\n    /** Inline style — a CSS string, or a property map (the reader passes `{ color }`-style objects). */\n    style?: string | Record<string, string | number>;\n    /** Advisory title (tooltip). */\n    title?: string;\n    /** ARIA role. */\n    role?: string;\n    /** Whether the element is hidden. */\n    hidden?: boolean;\n    /** Tab order. */\n    tabindex?: number;\n    /** Text directionality. */\n    dir?: \"ltr\" | \"rtl\" | \"auto\";\n    /** Language tag. */\n    lang?: string;\n    /** The reader's list/`@for` reconciliation key (rides through props; ignored by static serialize). */\n    key?: string | number;\n    /** Anything else — custom attributes, `data-*`/`aria-*`, event handlers — stays legal. */\n    [attr: string]: unknown;\n}\n/** `<a>` — hyperlink. */\ninterface NotaAnchorAttributes extends NotaGlobalAttributes {\n    href?: string;\n    target?: \"_self\" | \"_blank\" | \"_parent\" | \"_top\" | (string & {});\n    rel?: string;\n    download?: string | boolean;\n}\n/** `<img>` — image. */\ninterface NotaImgAttributes extends NotaGlobalAttributes {\n    src?: string;\n    alt?: string;\n    width?: number | string;\n    height?: number | string;\n    loading?: \"eager\" | \"lazy\";\n    decoding?: \"sync\" | \"async\" | \"auto\";\n}\n/** `<input>` — form control. */\ninterface NotaInputAttributes extends NotaGlobalAttributes {\n    type?: string;\n    name?: string;\n    value?: string | number;\n    placeholder?: string;\n    disabled?: boolean;\n    checked?: boolean;\n    required?: boolean;\n    readonly?: boolean;\n}\n/** `<label>` — form label. */\ninterface NotaLabelAttributes extends NotaGlobalAttributes {\n    /** HTML `for` (not React's `htmlFor`). */\n    for?: string;\n}\n/** `<td>`/`<th>` — table cells. */\ninterface NotaTableCellAttributes extends NotaGlobalAttributes {\n    colspan?: number;\n    rowspan?: number;\n    headers?: string;\n    scope?: \"row\" | \"col\" | \"rowgroup\" | \"colgroup\";\n}\n/** `<ol>` — ordered list. */\ninterface NotaOlAttributes extends NotaGlobalAttributes {\n    start?: number;\n    reversed?: boolean;\n    type?: \"1\" | \"a\" | \"A\" | \"i\" | \"I\";\n}\n/**\n * The per-tag attribute map. Explicit entries give the distinctive attributes of common elements;\n * the string index signature is the fallback for every other tag (custom elements, `nota-*`\n * sentinels, anything the reader emits) — permissive, so unknown tags never error.\n *\n * A generic host element (`<p>`, `<div>`, `<span>`, `<h1>`…) resolves through the index signature to\n * {@link NotaGlobalAttributes}. `<a>`/`<img>`/`<input>`/… resolve to their specific attributes.\n */\ninterface NotaIntrinsicElements {\n    a: NotaAnchorAttributes;\n    img: NotaImgAttributes;\n    input: NotaInputAttributes;\n    label: NotaLabelAttributes;\n    td: NotaTableCellAttributes;\n    th: NotaTableCellAttributes;\n    ol: NotaOlAttributes;\n    /** Fallback: any other tag string is legal and gets the global attributes. */\n    [tag: string]: NotaGlobalAttributes;\n}\n/**\n * The props type for `h(tag, props, …)` when `tag` is a **string literal** `K`: the specific\n * attributes for a known `K`, or the permissive {@link NotaGlobalAttributes} for any other string.\n */\ntype NotaHostProps<K extends string> = K extends keyof NotaIntrinsicElements ? NotaIntrinsicElements[K] : NotaGlobalAttributes;\n\n/**\n * The pre-rendered-HTML marker `raw(html)`: a `raw(slot)` an adapter injects as innerHTML instead\n * of escaping.\n *\n * `island()` pre-serializes a boundary's *static* children to an HTML string (the \"slot\"), then\n * hands them to the framework as `adapter.h(comp, props, raw(slot))`. The slot is already HTML — it\n * must NOT be re-escaped or re-parsed into framework vnodes. `raw(slot)` is the cross-package signal\n * for that: an adapter that finds a `RawHtml` among an element's children renders it as the\n * element's innerHTML (React `dangerouslySetInnerHTML`, Solid `innerHTML`) and emits no JSX children.\n *\n * It is a *branded object* (not a bare string) so it survives {@link flatten} unchanged\n * (flatten treats it as an opaque vnode and pushes it) and is unambiguously distinguishable from an\n * ordinary text child. Both `@nota-lang/react` and `@nota-lang/solid` import {@link isRaw} to detect\n * it — keeping the marker shape owned here, in the runtime, is what lets the two adapters agree.\n */\n/** The unique brand key tagging a {@link RawHtml} value (private symbol → no accidental collision). */\ndeclare const RAW: unique symbol;\n/** A pre-rendered HTML slot: opaque markup an adapter injects verbatim as innerHTML. */\ninterface RawHtml {\n    readonly [RAW]: true;\n    /** The raw HTML string (already escaped/serialized by {@link serialize}). */\n    readonly html: string;\n    /**\n     * Block-level in the static path (a raw leaf declares its own blockness): `struct` treats a block raw like a block\n     * *sibling* — it flushes the surrounding paragraph run and is never `<p>`-wrapped. Default\n     * `false`: an inline raw (e.g. KaTeX MathML) joins the run. Set it for raw whose HTML is\n     * block-shaped (shiki's `<pre>`, display math) so grouping never nests it in a `<p>`.\n     */\n    readonly block?: boolean;\n}\n/** Wrap an already-serialized HTML string as a {@link RawHtml} marker. */\ndeclare function raw(html: string, opts?: {\n    block?: boolean;\n}): RawHtml;\n/** True when `v` is a {@link RawHtml} marker (used by adapters to switch to innerHTML rendering). */\ndeclare function isRaw(v: unknown): v is RawHtml;\n\n/**\n * Doc-state: marks & queries (design/decode.md §Doc-state: marks & queries).\n *\n * The two-pass document constructs — table of contents, heading numbers/counters, `@ref`,\n * footnotes, citations/bibliography — need *whole-document* knowledge before their own position\n * serializes. `Doc()` already produces the **complete** vnode tree before any decoding, so forward\n * reference is a *scoping* problem, not a temporal one (one evaluation, tree passes — Scribble\n * collect/resolve, NOT two evaluations).\n *\n * This module owns the two opaque leaves and the passes that resolve them:\n *\n * - {@link mark}`(kind, data)` — a {@link MarkLeaf}: registers an index entry at its tree position,\n *   removed by {@link force}.\n * - {@link query}`(fn)` — a {@link QueryLeaf}: `fn: (doc: DocIndex) => children`, forced against the\n *   built index (its output normalized like any `h` child).\n *\n * Both survive {@link flatten}, pass through {@link struct} untouched, and are\n * runtime exports the **reader never emits** (prelude/user surface). At `▸ = true` (inside a\n * component body) both constructors throw — doc-state is a static-document construct; islands own\n * any secondary state.\n *\n * The decode pipeline at `▸ = false` (wired in `./serialize` + {@link decode}) is\n * `serialize ∘ struct ∘ force ∘ index ∘ normalize`:\n * - {@link normalize} hoists static-template expansion + transparent-fragment splicing to a\n *   whole-tree pre-pass, so the index sees marks produced *by templates*;\n * - {@link indexDoc} = one DFS collecting mark leaves into a {@link DocIndex};\n * - {@link force} = remove mark leaves and splice each query's (normalized, recursively forced)\n *   output in place — **before** grouping, so forced output participates in list/para/section\n *   grouping like authored content and none of the grouping passes ever see a doc-state leaf.\n *\n * ## Import hygiene (\"guard the seams\")\n * `doc.ts` may import `vnode`/`component`/`flag`/`struct`, **never** `serialize`/`h` — the decode\n * pipeline lives in `serialize.ts` (which already imports `struct`), so `doc.ts` never depends on\n * it. The `vnode ↔ doc` and `struct ↔ doc` edges are cycles, but every cross-module binding is used\n * only inside a function body (never at module-init), so ESM live bindings resolve them safely.\n */\n/** Brand key tagging a {@link MarkLeaf} (private symbol → no accidental collision). */\ndeclare const MARK: unique symbol;\n/** Brand key tagging a {@link QueryLeaf}. */\ndeclare const QUERY: unique symbol;\n/**\n * A **mark leaf**: an index entry registered at its tree position. The mark object *is* its own\n * handle — {@link DocIndex.get} looks it up by identity — so a policy layer (the prelude's\n * `@label`/`@ref`) can hold the leaf it emitted and later resolve it against the built index.\n * {@link force} removes marks from the tree (they render nowhere).\n */\ninterface MarkLeaf {\n    readonly [MARK]: true;\n    /** The mark's category (`\"heading\"`, `\"footnote\"`, `\"cite\"`, …); groups it in {@link DocIndex.all}. */\n    readonly kind: string;\n    /**\n     * Arbitrary attached data (defaults to `{}`). A vnode-valued `data.content` field is **walked** by\n     * {@link indexDoc} so marks *inside* it (e.g. footnote content) are indexed at the parent mark's\n     * position — but it is **not** template-expanded (v1: a mark hidden behind an unexpanded template\n     * there surfaces at force time and correctly hits the new-mark error).\n     */\n    readonly data: Record<string, unknown>;\n}\n/**\n * A **query leaf**: `fn: (doc: DocIndex) => children`, forced against the built index. {@link force}\n * replaces it with `normalize(fn(doc))`, recursively forced (a query's output may itself hold\n * queries — resolved against the same *frozen* index, so it terminates). Query output may **not**\n * introduce new marks (pointed error; no fixpoint iteration — a doc-state hard rule).\n */\ninterface QueryLeaf {\n    readonly [QUERY]: true;\n    /** The resolver: reads the whole-document {@link DocIndex}, returns children (normalized on splice). */\n    readonly fn: (doc: DocIndex) => unknown;\n}\n/**\n * Register a {@link MarkLeaf} at this tree position. `data` defaults to `{}`. Throws at `▸ = true`\n * (inside a component body): doc-state is static-document-only.\n */\ndeclare function mark(kind: string, data?: Record<string, unknown>): MarkLeaf;\n/**\n * Register a {@link QueryLeaf}: `fn` runs against the built {@link DocIndex} during {@link force}.\n * Throws at `▸ = true` (see {@link mark}).\n */\ndeclare function query(fn: (doc: DocIndex) => unknown): QueryLeaf;\n/** True when `v` is a {@link MarkLeaf}. */\ndeclare function isMark(v: unknown): v is MarkLeaf;\n/** True when `v` is a {@link QueryLeaf}. */\ndeclare function isQuery(v: unknown): v is QueryLeaf;\n/**\n * One resolved mark. `seq` is the per-kind 1-based ordinal (heading #3 of the headings); `pos` is\n * the global DFS ordinal — a *total* order across kinds — so a policy layer can interleave kinds by\n * position (a label binds to the nearest preceding heading by `pos`).\n */\ninterface IndexedMark {\n    readonly kind: string;\n    readonly data: Record<string, unknown>;\n    /** Per-kind 1-based ordinal (document order within the kind). */\n    readonly seq: number;\n    /** Global DFS ordinal (total order across all kinds). */\n    readonly pos: number;\n}\n/**\n * The built document index: the whole-document knowledge a {@link query} resolves against. Built\n * once by {@link indexDoc} and frozen for the {@link force} pass.\n *\n * Surface: {@link all} (document order, empty for an unknown kind) and {@link get}\n * (identity lookup — the mark leaf object is the handle). {@link has} is the membership test\n * {@link force} uses as its new-mark guard (an internal detail of the pass, harmless on the query\n * surface).\n */\ndeclare class DocIndex {\n    private readonly byMark;\n    private readonly byKind;\n    /** @internal — populated by {@link indexDoc} in DFS order (so {@link all} is document order). */\n    _record(m: MarkLeaf, entry: IndexedMark): void;\n    /** All marks of `kind` in document order; a fresh **empty** array for an unknown kind. */\n    all(kind: string): readonly IndexedMark[];\n    /** The entry for a mark leaf (identity lookup). Throws a pointed error for an unindexed mark. */\n    get(m: MarkLeaf): IndexedMark;\n    /** @internal — membership test; {@link force} uses it as the new-mark guard (query output may not introduce marks). */\n    has(m: MarkLeaf): boolean;\n}\n/**\n * Build the {@link DocIndex} in a single DFS over `root` (which must already be\n * {@link normalize}'d, so marks produced by templates are exposed and fragments are\n * spliced). Recurses into element children **including component-boundary children** (they are\n * static tree; bodies are functions and are never invoked). Strings, {@link RawHtml}, and\n * {@link QueryLeaf} leaves are skipped. On a {@link MarkLeaf}: record its entry, then walk a\n * vnode-valued `data.content` field so marks nested there index right under the parent mark's `pos`.\n * Props (other than `data.content`) are not descended into.\n */\ndeclare function indexDoc(root: VNode): DocIndex;\n/**\n * Resolve doc-state leaves against `doc`, rebuilding the tree (pure map over element nodes). Per\n * child:\n * - a **mark leaf in the index** → dropped (rendered nowhere);\n * - a **mark leaf not in the index** → pointed error (membership doubles as the new-mark check,\n *   since every tree mark was indexed);\n * - a **query leaf** → `normalize` each of `flatten([fn(doc)])`, then recursively force it (queries\n *   may nest; the index is frozen, so it terminates), spliced into the sibling stream.\n *\n * {@link RawHtml} leaves are opaque; props are untouched; component-boundary children are\n * descended into (they are static tree). Runs **before** grouping, so the grouping passes never see\n * a doc-state leaf.\n */\ndeclare function force(root: VNode, doc: DocIndex): VNode;\n/** Register (or replace) a named trailer thunk. Persistent across renders. */\ndeclare function registerTrailer(name: string, thunk: () => unknown): void;\n/**\n * Clear all trailers (or just the named ones). A test/dev hook mirroring\n * {@link clearRegisteredComponents}; production registers once and never clears.\n */\ndeclare function clearTrailers(...names: string[]): void;\n/** @internal — the decode pipeline runs each trailer thunk in registration order. */\ndeclare function runTrailers(): unknown[];\n/** @internal — does any trailer exist? (decode wraps the doc in a FRAG only when it does). */\ndeclare function hasTrailers(): boolean;\n\n/**\n * The Nota vnode data model.\n *\n * ```\n * v ::= string                       // text leaf\n *     | { tag, props, children }      // tag: host string (decode owns) | CompFn (boundary)\n * ```\n *\n * A static build (`▸ = false`) yields a tree of plain `{tag, props, children}` nodes.\n * Component-tagged nodes are *deferred*: `h(Colorized, …)` records a boundary\n * rather than invoking `Colorized`. The `struct`/`serialize` passes consume this model.\n */\n/**\n * A **plain function tag**: a static template. `struct` expands it eagerly —\n * invoking it with `{ children, …props }` and splicing the result into the sibling stream *before*\n * grouping, so a template's list sentinels coalesce with its siblings'. Contrast {@link CompFn}:\n * the marked constructors buy *deferral* (an island boundary, `kind`-driven paragraph grouping,\n * hydration by name); a bare function buys none of that and needs none — it is inlined at decode\n * time. Under `▸ = true` the framework adapter invokes plain function tags natively.\n */\ntype TemplateFn = (props: CompProps) => unknown;\n/**\n * The fragment tag sentinel. A unique `symbol` so it can never collide with a host tag string or a\n * component function, and so\n * `tag === FRAG` is an unambiguous structural test.\n */\ndeclare const FRAG: unique symbol;\ntype Frag = typeof FRAG;\n/** A non-text vnode: a host element, a fragment, a template, or a component boundary. */\ninterface ElementVNode {\n    /**\n     * - `string` → host element (lowercase tag); `decode` owns and restructures it.\n     * - {@link FRAG} → a fragment (transparent grouping; carries no DOM element of its own).\n     * - {@link CompFn} → a component boundary; the framework owns its body, `struct` stops here.\n     * - {@link TemplateFn} (any unmarked function) → a static template; `struct` expands it eagerly.\n     */\n    tag: string | Frag | CompFn | TemplateFn;\n    /** Props object. Always present (defaults to `{}`); never `null`/`undefined` on a built node. */\n    props: Record<string, unknown>;\n    /** Already-flattened child vnodes (see {@link flatten}). */\n    children: VNode[];\n}\n/**\n * A vnode is a text leaf, an element/fragment/boundary node, a {@link RawHtml} leaf — pre-rendered\n * HTML that the static path passes through opaquely (`struct` never descends, `serialize` emits it\n * verbatim) — or a {@link MarkLeaf}/{@link QueryLeaf} **doc-state** leaf:\n * opaque to `flatten`/`struct`, resolved (marks removed, queries spliced) by `decode`'s\n * `force` pass *before* grouping, so serialize never sees one. Raw leaves are how the prelude's\n * KaTeX output enters the tree without re-escaping; mark/query leaves are how forward-referencing\n * constructs (TOC, `@ref`, footnotes) index and resolve against the whole document.\n */\ntype VNode = string | ElementVNode | RawHtml | MarkLeaf | QueryLeaf;\n/** True when `v` is a non-text vnode (has a `tag`/`props`/`children` shape). A {@link RawHtml}\n *  leaf and the doc-state {@link MarkLeaf}/{@link QueryLeaf} leaves are *not* elements — they are\n *  opaque to every structural pass. */\ndeclare function isElement(v: VNode): v is ElementVNode;\n/** True when `v` is a fragment node. */\ndeclare function isFragment(v: VNode): v is ElementVNode & {\n    tag: Frag;\n};\n/**\n * A raw child argument as it arrives at `h`/`Fragment`, before normalization. The emitted code\n * passes strings, numbers, booleans, nullish, nested vnodes, and arrays thereof (e.g.\n * `[\"a\",\"b\"].map(...)` yields an array child). {@link flatten} normalizes all of these.\n */\ntype ChildArg = VNode | number | boolean | null | undefined | ChildArg[];\n/**\n * Normalize the variadic child arguments of `h`/`Fragment` into a flat `VNode[]`.\n *\n * Rules (one pass; arrays flattened exactly **one level**, matching the two emitted call shapes\n * `h(\"nota-ul-li\", {}, [child])` and `h(C, {}, x)`):\n *\n * - **Arrays are spliced in** one level deep. `@for`/`@if` lowerings produce an array child\n *   (`xs.map(...)`); splicing it makes its elements direct siblings. Nested arrays recurse so a\n *   `.map` returning fragments-of-arrays still flattens fully.\n * - **Strings pass through** unchanged (they are text leaves; whitespace is significant — the\n *   reader already applied the Scribble algorithm, so we must not trim or merge here).\n * - **Numbers are coerced to text** via `String(n)` (JSX-style). `0` and `NaN` are kept as\n *   `\"0\"`/`\"NaN\"` — numeric, not nullish.\n * - **Nullish and booleans are dropped**: `null`, `undefined`, `false`, **and** `true`. This is\n *   the usual JSX convention where `cond && <x/>` renders nothing for a falsy `cond`; we extend\n *   it to drop `true` as well so that `@if`-style guards never leak a stray `\"true\"` text node.\n *   (`@if (c) {a}` lowers to `c ? Fragment(\"a\") : null`, so a dropped `null` is the\n *   common case; dropping bare booleans is the documented, conservative choice.)\n * - Existing `ElementVNode`s pass through untouched.\n */\ndeclare function flatten(children: readonly ChildArg[]): VNode[];\n\n/**\n * Component constructors.\n *\n * `inlineComponent` / `blockComponent` wrap a user function into a *marked* component function.\n * The mark (`isComp`, `kind`) is what `struct`/`serialize` branch on: `isComp` distinguishes a\n * component boundary from a host node, and `kind` drives `<p>` grouping (an inline component joins\n * a paragraph run; a block component flushes it).\n */\n/** Props handed to a component: its decoded static `children` plus authored props. */\ninterface CompProps {\n    children: VNode[];\n    [key: string]: unknown;\n}\n/** A user-authored component body: `(children, props) => markup`. */\ntype CompBody = (children: VNode[], props: CompProps) => unknown;\n/** A marked component function (the value `h(C, …)` records as a boundary tag). */\ninterface CompFn {\n    (props: CompProps): unknown;\n    /** Marker: this function is a Nota component boundary (not a plain function passed as a tag). */\n    isComp: true;\n    /** Drives `<p>` grouping in {@link struct}: `\"inline\"` joins a run, `\"block\"` flushes it. */\n    kind: \"inline\" | \"block\";\n    /**\n     * The stable/export name. Set from the constructor's optional 2nd `name`\n     * argument; `nameOf(CompFn) := CompFn.compName` is what {@link island} writes into\n     * the manifest's `comp` field.\n     *\n     * **Why a passed name and not `fn.name`:** the reader hoists a `%let Name = inlineComponent(…)`\n     * binding to module scope, but the constructor's *returned* function is the value of a\n     * `CallExpression` initializer, so JS never name-evaluates it — `marked.name` is `\"\"` (or\n     * `\"marked\"`). The reader therefore passes the authored name explicitly. `undefined` when the\n     * caller omits it (e.g. unit-test fixtures that never reach `island`).\n     */\n    compName?: string;\n}\n/**\n * An inline component: joins surrounding inline content inside a `<p>` (kind `\"inline\"`).\n *\n * `name` is the stable/export name the reader passes (`inlineComponent(fn, \"Colorized\")`); it is\n * recorded as `compName` and surfaces as the island manifest's `comp`. Optional so hand-written\n * fixtures that never island a component may omit it.\n */\ndeclare function inlineComponent(fn: CompBody, name?: string): CompFn;\n/**\n * A block component: flushes the current paragraph run and stands on its own (kind `\"block\"`).\n * `name` behaves as in {@link inlineComponent}.\n */\ndeclare function blockComponent(fn: CompBody, name?: string): CompFn;\n/**\n * True when `tag` is a Nota component function (a boundary). Used by `struct`/`serialize` to\n * decide whether to stop at a boundary vs. recurse into a host node. Narrowed by the `isComp`\n * mark: a *plain* function used as a tag is not a boundary but a **static template** —\n * `struct` expands it eagerly, splicing its output into the sibling stream. The marked\n * constructors buy what only a boundary can have: deferral, `kind`-driven grouping, islands.\n */\ndeclare function isComp(tag: unknown): tag is CompFn;\n/**\n * The component's manifest name (`CompFn.compName`), or `\"anonymous\"` when unset.\n * {@link island} writes this into `manifest[id].comp`. Under replay hydration the\n * manifest is debug metadata only — the client hydrates by *replaying* the document (which recovers the live\n * `CompFn` directly), not by resolving this name — so a missing name is no longer fatal. The reader\n * still attaches it for readable manifests; a nameless boundary (e.g. a hand-written fixture, or a\n * component whose binding the reader could not name) falls back to `\"anonymous\"`.\n */\ndeclare function nameOf(tag: CompFn): string;\n\n/**\n * The context-sensitive primitives `h` / `Fragment` / `decode`.\n *\n * Under `▸ = false` (a static build) these build inert Nota vnodes and run the SSG pass; under\n * `▸ = true` (inside a component body during SSR) they delegate to the ambient framework adapter\n * (`@nota-lang/{react,solid}`). With no adapter injected, the `▸ = true` branches throw a pointed\n * \"no adapter injected\" error via `getAdapter()`.\n */\n/**\n * Remove `children` from a component/slot's prop type for the `h(tag, props, …)` call site — the\n * children come from the trailing `h` args (the decoded body), not the props object. A *key-remapped*\n * mapped type (not the built-in `Omit`): over a prop type with a permissive `[prop: string]: unknown`\n * index signature, `Omit` collapses to a bare index signature and drops the named prop types (so a\n * wrong `rank` on `Heading` would go unchecked); this remap preserves the named props (value-checked)\n * *and* the index signature (extras stay legal).\n */\ntype OmitChildren<P> = {\n    [K in keyof P as K extends \"children\" ? never : K]: P[K];\n};\n/**\n * Hyperscript. `t` is a host string or a component/template function; `p` is a props object or\n * `null`.\n *\n * ```\n * ▸ = false → ⟨t, p ?? {}, flatten(children)⟩          // inert nota vnode; component NOT invoked\n * ▸ = true  → Adapter.h(t, p, flatten(children))        // framework hyperscript\n * ```\n *\n * Component tags are **not** invoked under the static build — `h(Colorized, …)` merely records\n * `Colorized` as the boundary `tag`; its body runs later, inside `island()`'s SSR.\n *\n * Both emitted call shapes are handled by {@link flatten}: `h(\"nota-ul-li\", {}, [child])` (one array\n * arg) and `h(C, {}, x)` (one scalar arg).\n *\n * **Typed emit surface (design/decode.md §The typed surface).** Two public overloads, tried in order:\n * 1. a **function tag** (a component from `inlineComponent`/`blockComponent`, or an ambient prelude\n *    slot like `Tex`/`Heading`) — `props` is the tag's own parameter type minus `children` (the\n *    children come from the trailing args / the decoded body), so `h(Heading, { rank: 1 }, …)`\n *    checks `rank`, and a prelude slot's real prop type flows without the old contravariant\n *    tag-assignability failure;\n * 2. a **string tag** — `props` is the Nota-owned {@link NotaHostProps} for that tag (`h(\"a\", {\n *    href })` completes/checks `href`; an unknown tag falls through to the permissive global\n *    attributes, so `nota-*` sentinels and custom elements stay legal).\n *\n * There is deliberately **no** loose `Record<string, unknown>` overload: it would swallow every\n * wrong-prop-value on a known tag (they would silently match `Record<string, unknown>` instead of\n * erroring). The loose signature below the overloads is the *implementation* only — not callable —\n * so a mistyped prop on a known tag is a real error.\n */\ndeclare function h<P extends object>(t: (props: P) => unknown, p: OmitChildren<P> | null, ...children: ChildArg[]): ElementVNode;\ndeclare function h<K extends string>(t: K, p: NotaHostProps<K> | null, ...children: ChildArg[]): ElementVNode;\n/**\n * Fragment constructor with an **optional leading props object**.\n *\n * ```\n * Fragment(props?, …children)\n *   ▸ = false → ⟨FRAG, props ?? {}, flatten(children)⟩      // first arg is props iff a plain non-vnode obj\n *   ▸ = true  → Adapter.Fragment(props, flatten(children))  // React: createElement(Fragment, props, …)\n * ```\n *\n * The first argument is props iff `isLeadingProps` (a plain object that is not an array /\n * string / {@link RawHtml} / {@link ElementVNode}); otherwise **all** arguments — including the\n * first — are children. This decodes both the reader's keyed `@for` emit `Fragment({ key: _i },\n * …body)` *and* the bare `Fragment([\"a\",\"b\"].map(...))` form (array first arg → child). At\n * `▸ = false` a `key` simply rides in the FRAG vnode's props — `struct`/`serialize` ignore it (static\n * HTML needs no reconciliation key). At `▸ = true` it is forwarded to the adapter.\n */\ndeclare function Fragment(propsOrFirstChild?: ChildArg | Record<string, unknown>, ...rest: ChildArg[]): ElementVNode;\n/**\n * The decode pass.\n *\n * ```\n * ▸ = false → decodeTree(v)            // the SSG pass: normalize → index → force → struct → serialize\n * ▸ = true  → v                        // identity inside a component body\n * ```\n *\n * Inside a component (`▸ = true`) every `h` already returned an opaque framework element, so there\n * is nothing for a restructuring pass to see and `decode` is the identity. Under the static build it\n * runs the full decode pipeline (`decodeTree` = `serialize ∘ struct ∘ force ∘ index ∘\n * normalize`): resolve doc-state marks/queries and append trailers, restructure the tree, then\n * stringify it to HTML. For a mark-free document this is byte-identical to `serialize(struct(v))`.\n */\ndeclare function decode(v: VNode): unknown;\n\ndeclare const useState: <T>(init: T) => [T, (v: T) => void];\ndeclare const CodeInline: (props: { lang?: string; [prop: string]: unknown }) => unknown;\ndeclare const CodeBlock: (props: { lang?: string; [prop: string]: unknown }) => unknown;\ndeclare const Tex: (props: { display?: boolean; [prop: string]: unknown }) => unknown;\ndeclare const Heading: (props: { rank: number; id?: string; [prop: string]: unknown }) => unknown;\ndeclare const Toc: (props: { [prop: string]: unknown }) => unknown;\ndeclare const Label: (props: { id?: string; [prop: string]: unknown }) => unknown;\ndeclare const Ref: (props: { id?: string; [prop: string]: unknown }) => unknown;\ndeclare const Footnote: (props: { [prop: string]: unknown }) => unknown;\ndeclare const FootnoteMark: (props: { label?: string; [prop: string]: unknown }) => unknown;\ndeclare const FootnoteText: (props: { label?: string; [prop: string]: unknown }) => unknown;\ndeclare const Footnotes: (props: { [prop: string]: unknown }) => unknown;\ndeclare const FootnotesList: (props: { [prop: string]: unknown }) => unknown;\ndeclare const Cite: (props: { [prop: string]: unknown }) => unknown;\ndeclare const Bibliography: (props: { [prop: string]: unknown }) => unknown;\ndeclare const Title: (props: { [prop: string]: unknown }) => unknown;\ndeclare const Definition: (props: { id: string; label?: unknown; tooltip?: unknown; block?: boolean; [prop: string]: unknown }) => unknown;\ndeclare function texRef(id: string, tex: string): string;\ndeclare function lstset(options: { lang?: string; theme?: string; langs?: unknown; themes?: unknown[] }): void;\ndeclare function mathset(options: { macros?: Record<string, string> }): void;\ndeclare function secset(options: { [k: string]: unknown }): void;\ndeclare function bibset(options: { [k: string]: unknown }): void;\ndeclare function registerComponents(components: Record<string, unknown>): void;\n";

/** The byte length every `generatedOffsets` entry is shifted by (a clean whole-lines constant). */
export const PREAMBLE_LENGTH = PREAMBLE.length;
